scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = inputs['N']
    MOD = inputs['MOD']

    # Calculate factorial mod MOD
    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD

    return float(result)

scripts.gcd_list:
import math

def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Calculate GCD of all values
    result = values[0]
    for i in range(1, len(values)):
        result = math.gcd(result, values[i])

    return float(result)

scripts.sum_integer_quotients:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    total = 0
    for i in range(len(A)):
        quotient = A[i] // B[i]  # Integer division
        total += quotient

    return float(total)

scripts.lcg_iterations:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    # Perform K updates
    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

